"""Remove the diagnosed disconnected 56-triangle L3 waist fragment, preserving all other payloads."""
from glb_checks import read,arr,ROOT
from pathlib import Path
import numpy as np,json,struct,hashlib,sys
p=Path(sys.argv[1]);m,b=read(p);oldsha=hashlib.sha256(p.read_bytes()).hexdigest();node=next(n for n in m['nodes'] if n.get('name')=='L3_Armour');pr=m['meshes'][node['mesh']]['primitives'][0];pts=arr(m,b,pr['attributes']['POSITION']);faces=arr(m,b,pr['indices']).reshape(-1,3)
lo=np.array([-.09580455,.82854718,-.17770167])-.0001;hi=np.array([-.05065023,.87948221,-.15157701])+.0001;inside=((pts>=lo)&(pts<=hi)).all(axis=1);remove=inside[faces].all(axis=1);assert remove.sum()==56,('unexpected fragment geometry',remove.sum());kept=faces[~remove].copy();accessor=dict(m['accessors'][pr['indices']]);oldview=m['bufferViews'][accessor['bufferView']];dtype=faces.dtype;payload=kept.astype(dtype).tobytes();b+=b'\0'*((-len(b))%4);offset=len(b);b+=payload;b+=b'\0'*((-len(b))%4);vi=len(m['bufferViews']);m['bufferViews'].append({'buffer':0,'byteOffset':offset,'byteLength':len(payload),'target':34963});accessor.update(bufferView=vi,byteOffset=0,count=kept.size,min=[int(kept.min())],max=[int(kept.max())]);ai=len(m['accessors']);m['accessors'].append(accessor);pr['indices']=ai;m['buffers'][0]['byteLength']=len(b)
j=json.dumps(m,separators=(',',':')).encode();j+=b' '*((-len(j))%4);p.write_bytes(struct.pack('<III',0x46546c67,2,28+len(j)+len(b))+struct.pack('<II',len(j),0x4e4f534a)+j+struct.pack('<II',len(b),0x004e4942)+b)
report={'inputSha256':oldsha,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'removedTriangles':56,'reason':'Disconnected 30-vertex waist shard visible at pixel177.5,390 in L3 phone capture','boundsGltf':[lo.tolist(),hi.tolist()],'otherPositionsWeightsMaterialsClipsUnchanged':True};(ROOT/'reports/L3-fragment-repair.json').write_text(json.dumps(report,indent=2));print(report)
